(()=>{
if(window.GameAccounts)return;
const KEY='tablegame-remembered-accounts-v1';
function list(){try{const a=JSON.parse(localStorage.getItem(KEY));return Array.isArray(a)?a.filter(x=>typeof x==='string'&&x.length<=254).slice(0,6):[]}catch{return []}}
function mount(form,username,password){
 form.querySelector('.account-memory')?.remove();
 const box=document.createElement('div');box.className='account-memory';
 box.innerHTML='<label class="account-choice">已登录过的账号<select aria-label="选择已登录账号"><option value="">选择账号</option></select></label><div class="account-options"><label><input type="checkbox" class="remember-account" checked>记住账号</label><label><input type="checkbox" class="remember-password">记住密码</label><button type="button" class="show-password">显示密码</button></div><button type="button" class="saved-login">使用已保存账号一键登录</button><p class="account-note" role="status">密码由浏览器安全保存和自动填充，登录状态保留30天。</p>';
 const target=password.parentElement?.tagName==='LABEL'?password.parentElement:password;target.insertAdjacentElement('afterend',box);
 const select=box.querySelector('select'),remember=box.querySelector('.remember-account'),savePassword=box.querySelector('.remember-password'),note=box.querySelector('.account-note');
 const translations={'已登录过的账号':'Previous accounts','选择账号':'Choose an account','选择已登录账号':'Choose a previous account','记住账号':'Remember account','记住密码':'Remember password','显示密码':'Show password','隐藏密码':'Hide password','使用已保存账号一键登录':'Sign in with a saved account','选择浏览器已保存的密码':'Choose a saved password','密码由浏览器安全保存和自动填充，登录状态保留30天。':'Your browser saves and fills passwords securely. Stay signed in for 30 days.','请在密码框选择浏览器保存的账号与密码，再点击登录。':'Choose a saved account and password in the password field, then sign in.','还没有可用的已保存密码，请先登录并勾选记住密码。':'No saved password is available. Sign in first and choose Remember password.','请使用密码框的自动填充入口，或输入密码登录。':'Use password autofill or enter your password to sign in.'};
 function localize(){if(!document.createTreeWalker)return;const en=document.documentElement.lang.startsWith('en'),map=en?translations:Object.fromEntries(Object.entries(translations).map(([zh,en])=>[en,zh])),walker=document.createTreeWalker(box,4);let node;while((node=walker.nextNode())){const text=node.nodeValue.trim();if(map[text])node.nodeValue=node.nodeValue.replace(text,map[text])}select.setAttribute('aria-label',en?'Choose a previous account':'选择已登录账号')}
 const recent=list();for(const name of recent){const o=document.createElement('option');o.value=o.textContent=name;select.append(o)}
 box.querySelector('.account-choice').hidden=!recent.length;
 if(recent.length&&!username.value){username.value=recent[0];select.value=recent[0]}
 select.onchange=()=>{if(!select.value)return;username.value=select.value;password.value='';password.type='password';box.querySelector('.show-password').textContent='显示密码';password.focus();localize()};
 box.querySelector('.show-password').onclick=()=>{password.type=password.type==='password'?'text':'password';box.querySelector('.show-password').textContent=password.type==='password'?'显示密码':'隐藏密码';localize()};
 const supported=!!window.PasswordCredential&&!!navigator.credentials?.get;
 const quick=box.querySelector('.saved-login');quick.textContent=supported?'使用已保存账号一键登录':'选择浏览器已保存的密码';
 quick.onclick=async()=>{if(!supported){password.focus();note.textContent='请在密码框选择浏览器保存的账号与密码，再点击登录。';localize();return}quick.disabled=true;try{const credential=await navigator.credentials.get({password:true,mediation:'required'});if(!credential){note.textContent='还没有可用的已保存密码，请先登录并勾选记住密码。';return}username.value=credential.id;password.value=credential.password;password.type='password';box.querySelector('.show-password').textContent='显示密码';form.requestSubmit()}catch{note.textContent='请使用密码框的自动填充入口，或输入密码登录。'}finally{quick.disabled=false;localize()}};
 localize();
 return {setLanguage:localize,remember(user){try{const names=list().filter(x=>x!==user.username);if(remember.checked)names.unshift(user.username);localStorage.setItem(KEY,JSON.stringify(names.slice(0,6)))}catch{}if(savePassword.checked&&window.PasswordCredential&&navigator.credentials?.store)try{const credential=new PasswordCredential({id:user.username,password:password.value,name:user.username});navigator.credentials.store(credential).catch(()=>{note.textContent='你仍可通过浏览器的保存密码提示记住密码。'})}catch{}},box};
}
const style=document.createElement('style');style.textContent='.account-memory{margin:12px 0;font:12px Microsoft YaHei,system-ui}.account-memory .account-choice{display:block;margin:10px 0}.account-memory .account-choice[hidden]{display:none}.account-memory select{box-sizing:border-box;width:100%;padding:10px;margin-top:6px;border:1px solid #ddd8cf;background:transparent;border-radius:10px;color:inherit;font:inherit}.account-memory .account-options{display:flex;flex-wrap:wrap;align-items:center;gap:12px;margin:10px 0}.account-memory .account-options label{display:inline-flex!important;align-items:center;gap:5px;font:inherit!important;margin:0!important}.account-memory .account-options input[type=checkbox]{display:inline-block!important;width:15px!important;height:15px!important;margin:0!important;padding:0!important;accent-color:#333}.account-memory button{font:inherit!important;cursor:pointer}.account-memory .show-password{width:auto!important;margin:0!important;padding:3px!important;background:transparent!important;color:inherit!important;border:0!important}.account-memory .saved-login{box-sizing:border-box;width:100%;padding:10px;border:1px solid #ddd8cf!important;border-radius:10px;background:transparent!important;color:inherit!important;font-weight:400!important}.account-memory .account-note{font-size:11px;line-height:1.7;color:#8b857a;margin:9px 0}';document.head.append(style);
window.GameAccounts={mount};
})();
